(7631575, 1237063, 65234, '<td valign="top">Awww! Cute portrait.</td>', 'Awww! Cute portrait.', '2019-06-01 12:33:39.000000', NULL, 1),
(7631576, 1237245, 65234, '<td valign="top">I love the light in this one. Very conflicted about the red trash can. I think I want it desaturated so it doesn''t draw my eye so much, but then maybe you wanted it to stand out. It''s a jarring modern element in a largely old-looking scene. Still pondering ... and bumping the score for making me stop and think.</td>', 'I love the light in this one. Very conflicted about the red trash can. I think I want it desaturated so it doesn''t draw my eye so much, but then maybe you wanted it to stand out. It''s a jarring modern element in a largely old-looking scene. Still pondering ... and bumping the score for making me stop and think.', '2019-06-01 12:38:51.000000', NULL, 1),
(7631577, 1237198, 65234, '<td valign="top">Nice perspective.</td>', 'Nice perspective.', '2019-06-01 12:39:05.000000', NULL, 1),
