(7632165, 1237230, 114285, '<td valign="top">Are you back in Europe, you cant help yourself can you. Congratulations</td>', 'Are you back in Europe, you cant help yourself can you. Congratulations', '2019-06-07 01:33:17.000000', NULL, 0),
(7632166, 1237151, 123833, '<td valign="top">I have seen this lake only with the snow or ice. Whistler is still my favorite skiing place in spite of having now skied in many places around Switzerland, France and Austria. Unfortunately we can''t go skiing to Canada any more due to the lack of skiing accident insurance :( <br/> <br/>Why is the sky so dark? Is it automatic conversion in this phone? Congrats on the red.</td>', 'I have seen this lake only with the snow or ice. Whistler is still my favorite skiing place in spite of having now skied in many places around Switzerland, France and Austria. Unfortunately we can''t go skiing to Canada any more due to the lack of skiing accident insurance :(  Why is the sky so dark? Is it automatic conversion in this phone? Congrats on the red.', '2019-06-07 01:33:37.000000', NULL, 0),
(7632167, 1237020, 114285, '<td valign="top">Im sure it was a beauty in its day, congratulations on your top five, it was nice meeting you.</td>', 'Im sure it was a beauty in its day, congratulations on your top five, it was nice meeting you.', '2019-06-07 01:33:59.000000', NULL, 0),
